struct Packet { uint word; float value; };
Packet SelectWord(float4 input) {
    Packet result;
    uint word = asuint(input.x);
    if (word < 0x80000000u) { word += 7u; }
    else { word ^= 0x85EBCA6Bu; }
    if (word == 0u) { result.word = 1u; result.value = input.y; return result; }
    result.word = word;
    result.value = input.z;
    return result;
}
float4 main(float4 input : COLOR0) : SV_Target {
    Packet selected = SelectWord(input);
    if (input.w != input.w) { return float4(selected.value, input.y, input.z, input.w); }
    return float4(asfloat(selected.word), input.y, input.z, input.w);
}
